$('clear-all').onclick=()=>run(async()=>{const active=liveItems(items);if(!active.length){toast('Kho hiện tại không có dữ liệu để xóa.');return}$('settings').close();if(await confirmAction('Xóa toàn bộ dữ liệu?','Xóa tất cả mục và tệp đính kèm trên mọi thiết bị sau khi đồng bộ. Mật khẩu kho vẫn được giữ. Hãy sao lưu trước nếu còn cần dữ liệu.')){const now=new Date().toISOString(),ids=new Set(active.map(x=>x.id));await persist(items.map(x=>ids.has(x.id)?tombstone(x,now):x));selected=null;category='Tất cả';render();toast('Đã xóa toàn bộ dữ liệu trong kho hiện tại.')}});
function chooseFile(mode){if(mode==='db'&&!key){toast('Hãy mở kho trước khi nhập .db.');return}$('file').value='';$('file').accept=mode==='db'?'.db,application/octet-stream':mode==='csv'?'.csv,text/csv':'.vault,.json,application/json';$('file').onchange=()=>run(async()=>{const file=$('file').files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('File vượt quá 10 MB.');if(mode==='db'){const generation=epoch,data=new Uint8Array(await file.arrayBuffer());if(generation!==epoch||!key){data.fill(0);return}try{inspectDatabase(data);clearDb();pendingDb=data;$('settings').close();$('db-filename').textContent=file.name;$('db-import').showModal();$('db-password').focus()}catch(e){data.fill(0);throw e}finally{$('file').value=''}return}const text=await file.text();if(mode==='csv'){const imported=parseCSV(text);if(!imported.length){toast('File có đúng cấu trúc nhưng không có mục dữ liệu.');return}if(!key){if(!localStorage.getItem(STORE))throw Error('Hãy tạo kho trong Cài đặt trước khi Import CSV.');$('settings').close();pendingImport=imported;$('gate-description').textContent=`Đã chọn ${imported.length} mục. Mở khóa hoặc tạo kho để nhập và mã hóa dữ liệu.`;toast('Nhập mật khẩu chính để hoàn tất Import.');return}if(items.length+imported.length>20000)throw Error('Kho vượt quá 20.000 mục.');$('settings').close();if(await confirmAction('Nhập CSV',`Nhập ${imported.length} mục vào kho? Các trường OTP và ghi chú sẽ được giữ nguyên. Mục trùng vẫn được nhập.`)){await persist([...items,...imported]);render();toast(`Đã nhập ${imported.length} mục.`)}}else{$('settings').close();await restoreEnvelope(JSON.parse(text))}$('file').value=''});$('file').click()}
async function restoreEnvelope(envelope){const {validate}=await import('./crypto.js');validate(envelope);if(!await confirmAction('Mở kho từ sao lưu','Kho trên thiết bị sẽ được thay thế. Nếu đã có kho, hãy tải bản sao lưu trước. Bạn cần mật khẩu chính của kho được mở.'))return;if(localStorage.getItem(STORE))download(JSON.parse(localStorage.getItem(STORE)));await navigator.locks.request('safeincloud-write',()=>{localStorage.setItem(STORE,JSON.stringify(envelope));localStorage.removeItem(BIO);localStorage.removeItem(FAILURES)});expected=localStorage.getItem(STORE);lock();toast('Đã mở bản mã. Nhập mật khẩu chính để kiểm tra và mở khóa. Nếu không mở được, khôi phục file vừa tải.')}
$('import').onclick=()=>chooseFile('csv');$('restore').onclick=()=>chooseFile('vault');
async function googleToken(interactive=true){if(token&&Date.now()<tokenExpiry){googleEmail=googleEmail||driveMeta().email||'';return token}if(navigator.onLine===false)throw Error('Không có kết nối Internet. Dữ liệu vẫn được lưu trên thiết bị.');if(!window.google?.accounts?.oauth2)await new Promise((res,rej)=>{const s=element('script');s.src='https://accounts.google.com/gsi/client';s.onload=res;s.onerror=()=>rej(Error('Không tải được đăng nhập Google. Kiểm tra kết nối.'));document.head.append(s)});oauthPending=true;return new Promise((resolve,reject)=>{const saved=driveMeta().email||'',client=google.accounts.oauth2.initTokenClient({client_id:DEFAULT_CLIENT,scope:'openid email https://www.googleapis.com/auth/drive.appdata',login_hint:saved||undefined,callback:async r=>{try{if(r.error)throw Error('Google từ chối đăng nhập: '+r.error);const profile=await fetch('https://www.googleapis.com/oauth2/v3/userinfo',{headers:{Authorization:'Bearer '+r.access_token}});if(!profile.ok)throw Error('Không đọc được địa chỉ tài khoản Google.');const email=String((await profile.json()).email||'').trim().toLowerCase();if(!email)throw Error('Tài khoản Google không cung cấp địa chỉ email.');if(saved&&saved.toLowerCase()!==email)throw Error(`Kho này đang đồng bộ với ${saved}. Hãy chọn đúng tài khoản Google.`);token=r.access_token;tokenExpiry=Date.now()+(Number(r.expires_in)-60)*1000;googleEmail=email;renderDrive();resolve(token)}catch(error){token=null;tokenExpiry=0;reject(error)}finally{oauthPending=false}},error_callback:()=>{oauthPending=false;reject(Error(interactive?'Đăng nhập chưa hoàn tất. Kiểm tra popup và Authorized JavaScript origins.':'Cần mở ứng dụng và kết nối lại tài khoản Google.'))}});client.requestAccessToken({prompt:interactive?'select_account':''})})}
async function driveFetch(path,options={},accessToken){const t=accessToken||await googleToken(true),r=await fetch('https://www.googleapis.com/'+path,{...options,headers:{Authorization:'Bearer '+t,...options.headers}});if(!r.ok){if(r.status===401){token=null;tokenExpiry=0}throw Error(`Google Drive báo lỗi ${r.status}. Kiểm tra quyền Drive API và đăng nhập lại.`)}return r}
async function findDriveFile(accessToken){const q="trashed = false and appProperties has { key='app' and value='safeincloud-v1' }",r=await driveFetch('drive/v3/files?spaces=appDataFolder&pageSize=20&orderBy=modifiedTime%20desc&fields=files(id,name,modifiedTime,appProperties)&q='+encodeURIComponent(q),{},accessToken),files=(await r.json()).files||[];return files.find(file=>file.appProperties?.role==='current')||files[0]||null}
async function readDrive(accessToken){const file=await findDriveFile(accessToken);if(!file)return null;const response=await driveFetch('drive/v3/files/'+encodeURIComponent(file.id)+'?alt=media',{},accessToken),envelope=await response.text();const{validate}=await import('./crypto.js');validate(JSON.parse(envelope));return{file,envelope}}
async function uploadEnvelope(envelope,accessToken,knownFile){const current=knownFile||await findDriveFile(accessToken),boundary='safeincloud_'+crypto.randomUUID(),name='AT_SafeInCloud.vault',meta={name,appProperties:{app:'safeincloud-v1',role:'current'}};if(!current)meta.parents=['appDataFolder'];const body=`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(meta)}\r\n--${boundary}\r\nContent-Type: application/json\r\n\r\n${envelope}\r\n--${boundary}--`,path=current?`upload/drive/v3/files/${encodeURIComponent(current.id)}?uploadType=multipart`:'upload/drive/v3/files?uploadType=multipart',response=await fetch('https://www.googleapis.com/'+path,{method:current?'PATCH':'POST',headers:{Authorization:'Bearer '+accessToken,'Content-Type':'multipart/related; boundary='+boundary},body});if(!response.ok)throw Error('Không cập nhật được kho chung trên Google Drive. Dữ liệu trên thiết bị được giữ nguyên.');const result=await response.json();return result.id||current?.id}
async function installDrive(envelope,fileId,hash){await navigator.locks.request('safeincloud-write',()=>{localStorage.setItem(STORE,envelope);localStorage.removeItem(BIO);localStorage.removeItem(FAILURES)});expected=envelope;saveDriveMeta(googleEmail,fileId,hash);lock();toast(`Đã đồng bộ dữ liệu từ ${googleEmail}. Nhập mật khẩu chính để mở kho.`)}
async function syncUnlocked(accessToken,notify=false){
 const generation=epoch,localEnvelope=localStorage.getItem(STORE),remote=await readDrive(accessToken);
 if(generation!==epoch||!key)return;
 if(!remote){const fileId=await uploadEnvelope(localEnvelope,accessToken);saveDriveMeta(googleEmail,fileId,await digest(localEnvelope));$('drive-status').textContent=`Đã đồng bộ với ${googleEmail}`;if(notify)toast('Đã tạo kho chung trên tài khoản Google.');return}
 let remoteItems;
 try{remoteItems=await openWithKey(JSON.parse(remote.envelope),key,salt)}catch(error){if(error.name==='OperationError'||/khóa khác/.test(error.message))throw Error('Kho của tài khoản Google dùng mật khẩu hoặc database khác. Hãy sao lưu dữ liệu cục bộ rồi mở kho Google trước; ứng dụng không ghi đè tự động.');throw error}
 const merged=mergeItems(items,remoteItems),localChanged=!sameItems(items,merged),remoteChanged=!sameItems(remoteItems,merged);let encoded=localEnvelope,fileId=remote.file.id;
 if(localChanged||remoteChanged){const sealed=await seal(merged,key,salt);encoded=JSON.stringify(sealed)}
 if(localChanged){await navigator.locks.request('safeincloud-write',()=>{if(generation!==epoch||localStorage.getItem(STORE)!==localEnvelope)throw Error('Dữ liệu vừa thay đổi; sẽ đồng bộ lại.');localStorage.setItem(STORE,encoded);expected=encoded});items=merged;render()}
 if(remoteChanged)fileId=await uploadEnvelope(encoded,accessToken,remote.file);
 const syncedHash=await digest(remoteChanged?encoded:remote.envelope);saveDriveMeta(googleEmail,fileId,syncedHash);$('drive-status').textContent=`Đã đồng bộ với ${googleEmail} · ${new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}`;if(notify)toast('Đã kiểm tra và đồng bộ dữ liệu mới trên các thiết bị.');
}
async function autoSync(interactive=false){
 if(!key||!driveMeta().email||navigator.onLine===false)return;
 if(busy||syncing){syncAgain=true;return}
 syncing=true;syncAgain=false;
 try{const accessToken=await googleToken(interactive);await syncUnlocked(accessToken,interactive)}catch(error){if(interactive)throw error;$('drive-status').textContent=/database khác|mật khẩu/.test(error.message)?error.message:'Đã lưu trên thiết bị · chờ kết nối lại Google'}finally{syncing=false;if(syncAgain)queueAutoSync(700)}
}
async function syncDrive(){
 const accessToken=await googleToken(true),local=localStorage.getItem(STORE),remote=!local?await readDrive(accessToken):null;
 if(!local){if(!remote)throw Error('Tài khoản Google này chưa có dữ liệu. Hãy tạo kho mới rồi đồng bộ.');await installDrive(remote.envelope,remote.file.id,await digest(remote.envelope));return}
 if(!key)throw Error('Hãy mở khóa kho trước khi đồng bộ.');await syncUnlocked(accessToken,true)
}
$('sync').onclick=()=>run(async()=>{$('settings').close();await syncDrive()});
document.querySelectorAll('[data-password]').forEach(b=>b.onclick=()=>{const input=$(b.dataset.password),show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Ẩn':'Hiện';b.setAttribute('aria-pressed',String(show))});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());['pointerdown','keydown','input'].forEach(e=>document.addEventListener(e,()=>lastActivity=Date.now(),{passive:true}));setInterval(()=>{if(key&&Date.now()-lastActivity>300000)lock()},1000);setInterval(()=>{if(key&&document.visibilityState!=='hidden')autoSync(false)},60000);document.addEventListener('visibilitychange',()=>{if(document.hidden){hiddenAt=Date.now();if(key&&!oauthPending&&!authPending)lock();else if(key){$('detail').replaceChildren();$('fields').replaceChildren();if($('editor').open)$('editor').close()}}else if(hiddenAt&&Date.now()-hiddenAt>300000)lock();else if(key){render();queueAutoSync(100)}});window.addEventListener('online',()=>queueAutoSync(100));window.addEventListener('focus',()=>{if(key)queueAutoSync(100)});window.addEventListener('storage',e=>{if(e.key===STORE){lock();expected=e.newValue;toast('Kho đã thay đổi ở cửa sổ khác. Hãy mở khóa lại.')}});window.addEventListener('pagehide',lock);gate();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});


function clearDb(){dbAttempt++;pendingDb?.fill(0);pendingDb=null;dbBusy=false;$('db-password').value='';$('db-password').type='password';$('db-status').textContent='';$('db-decrypt').disabled=false;}
$('import-db').onclick=()=>chooseFile('db');
$('db-import').addEventListener('close',clearDb);
$('db-import-form').onsubmit=e=>{e.preventDefault();if(dbBusy||!pendingDb||!key)return;run(async()=>{
 const ticket=epoch,attempt=dbAttempt,data=pendingDb.slice();let password=$('db-password').value;
 if(!password){$('db-status').textContent='Hãy nhập mật khẩu của file .db.';data.fill(0);return}
 $('db-password').value='';dbBusy=true;$('db-decrypt').disabled=true;$('db-status').textContent='Đang giải mã trên thiết bị…';let result;
 try{
  result=await importDatabase(data,password);password='';
  if(ticket!==epoch||attempt!==dbAttempt||!key)return;
  if(items.length+result.items.length>20000)throw Error('Kho vượt quá 20.000 mục.');
  $('db-import').close();clearDb();
  if(!result.items.length){toast('File không có mục đang sử dụng để nhập.');return}
  const fileSummary=result.attachments?` Phục hồi được ${result.attachments} tệp đính kèm${result.skippedAttachments?`; bỏ qua ${result.skippedAttachments} tệp lỗi hoặc quá lớn`:''}.`:result.skippedAttachments?` Bỏ qua ${result.skippedAttachments} tệp đính kèm lỗi hoặc quá lớn.`:'';
  const historySummary=result.skippedHistory?` Bỏ qua ${result.skippedHistory} trường hoặc giá trị Lịch sử.`:'';
  const accepted=await confirmAction('Nhập dữ liệu SafeInCloud',`Đã giải mã ${result.items.length} mục.${fileSummary}${historySummary} Bỏ qua ${result.templates} mẫu và ${result.deleted} mục đã xóa. Thêm vào kho hiện tại? Mục trùng vẫn được nhập. Dữ liệu và tệp đính kèm sẽ được mã hóa bằng mật khẩu kho hiện tại.`);
  if(!accepted||ticket!==epoch||!key)return;
  let restored=result.attachments,skipped=result.skippedAttachments;
  try{await persist([...items,...result.items])}catch(error){
   if(!restored||!(/quota|storage|dung lượng/i.test(`${error.name} ${error.message}`)))throw error;
   const withoutFiles=result.items.map(item=>{const copy={...item};delete copy.attachments;return copy});
   await persist([...items,...withoutFiles]);skipped+=restored;restored=0;
  }
  render();toast(`Đã nhập ${result.items.length} mục${restored?` và ${restored} tệp đính kèm`:''} từ .db.${skipped?` Đã bỏ qua ${skipped} tệp không thể lưu.`:''} Hãy sao lưu AT_SafeInCloud.vault.`);
 }catch(error){if(ticket===epoch&&attempt===dbAttempt&&key)$('db-status').textContent=error.message;else if(ticket===epoch&&key)throw error;}
 finally{password='';data.fill(0);if(result)result.items.length=0;if(attempt===dbAttempt){dbBusy=false;$('db-decrypt').disabled=false;}}
 });};
